// Suma las ventas de los últimos 7 días
const rows = $input.all().map(i => i.json);
const num = v => parseFloat(String(v ?? '').replace(/[^0-9.,-]/g,'').replace(/\.(?=\d{3})/g,'').replace(',', '.')) || 0;
const getMonto = r => num(r.total ?? r.monto ?? r.valor ?? r.Total ?? r.Monto ?? 0);
const hace7 = Date.now() - 7*24*3600*1000;
const getFecha = r => { const d = new Date(r.fecha ?? r.Fecha ?? r.date ?? 0); return isNaN(d) ? null : d.getTime(); };
const recientes = rows.filter(r => { const f = getFecha(r); return f === null || f >= hace7; });
const total = recientes.reduce((s,r) => s + getMonto(r), 0);
const n = recientes.length;
const ticket = n ? total / n : 0;
const fmt = x => '$' + Math.round(x).toLocaleString('es-CO');
return [{ json: { ventas: n, total, ticket, resumen:
  `Reporte semanal de ventas\n\nVentas: ${n}\nIngresos: ${fmt(total)}\nTicket promedio: ${fmt(ticket)}` } }];
